import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ===== STATE =====
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [smsConversation, setSmsConversation] = useState([]);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [matches, setMatches] = useState([]);
  const [activeTab, setActiveTab] = useState('discover');
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [phoneNumber, setPhoneNumber] = useState('');
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [profileData, setProfileData] = useState(null);
  const [requestStatus, setRequestStatus] = useState(null);

  // ============================================
  // STEPS DEFINITION - COMPLETE SMS FLOW
  // ============================================

  const STEPS = [
    // STEP 1: ACTIVATION
    {
      id: 1,
      title: 'Service Activation',
      subtitle: 'Send PENZI to activate',
      icon: '💑',
      endpoint: '/activate',
      method: 'POST',
      fields: [
        { key: 'penzi', label: 'Enter Activation Code', placeholder: 'Type PENZI', type: 'text' }
      ],
      buildBody: (data) => ({ penzi: data.penzi || 'penzi' }),
      isActivation: true,
      userMessage: 'PENZI',
      systemMessage: 'Welcome to our dating service with 6000 potential dating partners! To register SMS start#name#age#gender#county#town to 22141. E.g., start#John Doe#26#Male#Nakuru#Naivasha'
    },
    // STEP 2: SERVICE REGISTRATION
    {
      id: 2,
      title: 'Service Registration',
      subtitle: 'Create your account',
      icon: '📝',
      endpoint: '/register',
      method: 'POST',
      fields: [
        { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel' },
        { key: 'name', label: '👤 Full Name', placeholder: 'John Doe', type: 'text' },
        { key: 'age', label: '🎂 Age', placeholder: '26', type: 'number' },
        { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
        { key: 'county', label: '📍 County', placeholder: 'Nakuru', type: 'text' },
        { key: 'town', label: '🏙️ Town/City', placeholder: 'Naivasha', type: 'text' }
      ],
      buildBody: (data) => ({
        phone_number: data.phone_number,
        name: data.name,
        age: data.age,
        gender: data.gender,
        county: data.county,
        town: data.town
      }),
      userMessage: (data) => `start#${data.name}#${data.age}#${data.gender}#${data.county}#${data.town}`,
      systemMessage: (data) => `Your profile has been created successfully ${data.name}. SMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141. E.g. details#diploma#driver#single#christian#mijikenda`
    },
    // STEP 3: DETAILS REGISTRATION
    {
      id: 3,
      title: 'Details Registration',
      subtitle: 'Complete your profile',
      icon: '📋',
      endpoint: '/{phone}/complete-profile',
      method: 'POST',
      fields: [
        { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
        { key: 'profession', label: '💼 Profession', placeholder: 'Accountant', type: 'text' },
        { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
        { key: 'religion', label: '⛪ Religion', placeholder: 'Christian', type: 'text' },
        { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Kikuyu', type: 'text' }
      ],
      requiresPhone: true,
      buildBody: (data) => ({
        education_level: data.education_level,
        profession: data.profession,
        marital_status: data.marital_status,
        religion: data.religion,
        ethnicity: data.ethnicity
      }),
      userMessage: (data) => `details#${data.education_level}#${data.profession}#${data.marital_status}#${data.religion}#${data.ethnicity}`,
      systemMessage: 'This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF. E.g., MYSELF chocolate, lovely, sexy etc.'
    },
    // STEP 4: SELF-DESCRIPTION
    {
      id: 4,
      title: 'Self-Description',
      subtitle: 'Tell us about yourself',
      icon: '💭',
      endpoint: '/{phone}/self-description',
      method: 'POST',
      fields: [
        { key: 'description', label: 'Describe yourself', placeholder: 'Hardworking, honest, family-oriented...', type: 'textarea' }
      ],
      requiresPhone: true,
      buildBody: (data) => ({ description: data.description }),
      userMessage: (data) => `MYSELF ${data.description}`,
      systemMessage: 'You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams. E.g., match#23-25#Kisumu'
    },
    // STEP 5: MATCHING REQUEST
    {
      id: 5,
      title: 'Matching Request',
      subtitle: 'Search for your match',
      icon: '❤️',
      endpoint: '/sms',
      method: 'POST',
      fields: [
        { key: 'age_range', label: '📅 Age Range', placeholder: '26-30', type: 'text' },
        { key: 'town', label: '📍 Town/City', placeholder: 'Nairobi', type: 'text' }
      ],
      requiresPhone: true,
      buildBody: (data) => ({
        phone_number: data.phone_number,
        message: `match#${data.age_range}#${data.town}`
      }),
      userMessage: (data) => `match#${data.age_range}#${data.town}`,
      isFinal: true
    }
  ];

  // ============================================
  // LOAD SAVED STATE
  // ============================================

  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);
        setCurrentStep(parsed.currentStep || 0);
        setCompletedSteps(new Set(parsed.completedSteps || []));
        setSmsConversation(parsed.smsConversation || []);
        setPhoneNumber(parsed.phoneNumber || '');
        setActivationDone(parsed.activationDone || false);
        setMatches(parsed.matches || []);
        if (parsed.currentUser) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================

  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        smsConversation,
        currentUser,
        phoneNumber,
        activationDone,
        matches
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, smsConversation, currentUser, phoneNumber, activationDone, matches]);

  // ============================================
  // CHECK SERVER
  // ============================================

  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPERS
  // ============================================

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / STEPS.length) * 100);
  };

  const goToStep = (index) => {
    if (index >= 0 && index < STEPS.length) {
      setCurrentStep(index);
    }
  };

  // ============================================
  // VIEW PROFILE FUNCTION
  // ============================================

  const viewProfile = (match) => {
    setSelectedMatch(match);
    setShowProfile(true);
  };

  // ============================================
  // EXPRESS INTEREST FUNCTION
  // ============================================

  const expressInterest = (match) => {
    addToConversation('📱 You', `Expressing interest in ${match.name} (${match.phone})`, false);
    addToConversation('🤖 System', `💕 Interest sent to ${match.name}! They will be notified.`, true);
    addNotification(`💕 Interest sent to ${match.name}!`);

    // Remove from matches
    setMatches(matches.filter(m => m.phone !== match.phone));
  };

  // ============================================
  // BUILD SMS PREVIEW
  // ============================================

  const buildSmsPreview = (step) => {
    if (step.id === 1) return 'PENZI';
    if (step.id === 2) {
      return `start#${formData.name || 'John Doe'}#${formData.age || '26'}#${formData.gender || 'Male'}#${formData.county || 'Nakuru'}#${formData.town || 'Naivasha'}`;
    }
    if (step.id === 3) {
      return `details#${formData.education_level || 'diploma'}#${formData.profession || 'driver'}#${formData.marital_status || 'single'}#${formData.religion || 'christian'}#${formData.ethnicity || 'mijikenda'}`;
    }
    if (step.id === 4) {
      return `MYSELF ${formData.description || 'Your description here'}`;
    }
    if (step.id === 5) {
      return `match#${formData.age_range || '26-30'}#${formData.town || 'Nairobi'}`;
    }
    return '';
  };

  // ============================================
  // EXECUTE API
  // ============================================

  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      let phone = formData.phone_number || phoneNumber || '0712345678';

      let endpoint = step.endpoint;
      if (step.requiresPhone) {
        endpoint = endpoint.replace('{phone}', phone);
      }

      const fullUrl = API_BASE + endpoint;
      console.log(`📡 Calling: ${step.method} ${fullUrl}`);

      let body = null;
      if (step.buildBody) {
        body = step.buildBody(formData);
        if (step.requiresPhone && !body.phone_number) {
          body.phone_number = phone;
        }
      }

      console.log('📦 Body:', body);

      const options = {
        method: step.method,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      };

      if (body && (step.method === 'POST' || step.method === 'PUT')) {
        options.body = JSON.stringify(body);
      }

      const response = await fetch(fullUrl, options);
      console.log(`📥 Status: ${response.status}`);

      let responseData;
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        responseData = await response.json();
      } else {
        responseData = await response.text();
      }

      console.log('📥 Response:', responseData);

      if (response.ok) {
        // -------- STEP 1: ACTIVATION --------
        if (step.id === 1) {
          const welcomeMsg = responseData?.message || step.systemMessage;
          addToConversation('📱 You', 'PENZI', false);
          addToConversation('🤖 System', welcomeMsg, true);

          setActivationDone(true);
          setResponseMessage('✅ Service activated successfully!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Service activated! Proceed to registration.');
          setPhoneNumber('0712345678');
        }

        // -------- STEP 2: REGISTRATION --------
        else if (step.id === 2) {
          const userMsg = step.userMessage(formData);
          const sysMsg = step.systemMessage(formData);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);

          setPhoneNumber(formData.phone_number || '0712345678');
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 3.');
        }

        // -------- STEP 3: DETAILS REGISTRATION --------
