          const userMsg = step.userMessage(formData);
          const sysMsg = step.systemMessage;

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);

          setResponseMessage('✅ Profile completed!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed! Proceed to step 4.');
        }

        // -------- STEP 4: SELF-DESCRIPTION --------
        else if (step.id === 4) {
          const userMsg = step.userMessage(formData);
          const sysMsg = step.systemMessage;

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);

          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 5.');
        }

        // -------- STEP 5: MATCHING REQUEST --------
        else if (step.id === 5) {
          const userMsg = step.userMessage(formData);
          addToConversation('📱 You', userMsg, false);

          let matchesData = [];
          if (responseData && responseData.matches) {
            matchesData = responseData.matches;
          } else {
            matchesData = [
              { phone: '0722010203', name: 'Lina Moraa', age: 29, town: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Kind-hearted and adventurous. Loves hiking.' },
              { phone: '0701223344', name: 'Dorine Gakii', age: 26, town: 'Nakuru', profession: 'Teacher', education: 'Diploma', religion: 'Christian', ethnicity: 'Kamba', description: 'Caring and dedicated. Loves children.' },
              { phone: '0700112233', name: 'Aisha Bahati', age: 27, town: 'Mombasa', profession: 'Accountant', education: 'Graduate', religion: 'Muslim', ethnicity: 'Swahili', description: 'Ambitious and hardworking.' },
              { phone: '0722040506', name: 'Pamela Nafula', age: 26, town: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', description: 'Tech enthusiast. Loves innovation.' },
              { phone: '0702556677', name: 'Maria Mwende', age: 28, town: 'Kasarani', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kamba', description: 'Diligent, loving, dedicated and will make you tick.' },
              { phone: '0708990011', name: 'Keziah Cheptab', age: 28, town: 'Eldoret', profession: 'Doctor', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kalenjin', description: 'Passionate about healthcare and community service.' }
            ];
          }

          setMatches(matchesData);

          const countMsg = `We have ${matchesData.length} ladies who match your choice! We will send you details of 3 of them shortly. To get more details about a lady, SMS her number e.g., 0722010203 to 22141`;
          addToConversation('🤖 System', countMsg, true);

          // Show first 3 matches
          const firstThree = matchesData.slice(0, 3);
          firstThree.forEach(m => {
            addToConversation('🤖 System', `${m.name} aged ${m.age}, ${m.phone}.`, true);
          });

          if (matchesData.length > 3) {
            addToConversation('🤖 System', `Send NEXT to 22141 to receive details of the remaining ${matchesData.length - 3} ladies`, true);
          }

          setResponseMessage(`✅ Found ${matchesData.length} matches!`);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));

          const user = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User'
          };
          setCurrentUser(user);
          setIsLoggedIn(true);
          addNotification(`🎉 Found ${matchesData.length} matches! Welcome to PENZI!`);
        }

      } else {
        const errorMsg = responseData?.message || responseData?.error || `Error ${response.status}`;
        setResponseMessage('❌ ' + errorMsg);
        setIsSuccess(false);
        setErrorDetails(`Status: ${response.status}`);
        addNotification(`❌ ${errorMsg}`, 'error');
      }

    } catch (error) {
      console.error('❌ API Error:', error);
      let errorMessage = 'Network Error';
      let errorDetail = '';

      if (error.message.includes('Failed to fetch')) {
        errorMessage = 'Cannot connect to the server.';
        errorDetail = `Make sure the backend is running at ${API_BASE}`;
      } else {
        errorMessage = error.message || 'An unknown error occurred.';
        errorDetail = 'Please check your connection and try again.';
      }

      setResponseMessage('❌ ' + errorMessage);
      setIsSuccess(false);
      setErrorDetails(errorDetail);
      addNotification(`❌ ${errorMessage}`, 'error');

    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // RENDER SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;

    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
